class singleton
{
public:
  singleton() {}
  virtual ~singleton();
};

enum device_id_t
{
  JOYSTICK1_DEVICE = 1,
  AI_JOYSTICK = 9
};

class input_device
{
public:
  device_id_t device_id;
  virtual ~input_device();
};

class AISurferController : public input_device
{
  char released_storage[280];
public:
  AISurferController();
};

class device_map_t
{
  input_device **begin_;
  input_device **end_;
  input_device **storage_end_;
public:
  device_map_t() : begin_(0), end_(0), storage_end_(0) {}
};

class control_map_t
{
  void *root_;
  unsigned count_;
  unsigned char key_compare_;
  unsigned char padding_[3];
public:
  control_map_t() : root_(0), count_(0), key_compare_(0)
  {
    padding_[0] = padding_[1] = padding_[2] = 0;
  }
};

class rumble_manager;

class input_mgr : public singleton
{
public:
  input_mgr();
  virtual ~input_mgr();
  void insert_device(input_device *);
  void scan_devices();
  void SetDefaultController(int cont) { default_controller = cont; }

private:
  rumble_manager *rumble_ptr;
  device_map_t device_map;
  control_map_t control_map;
  int default_controller;
  unsigned int flags;

protected:
  input_device *joystick_devices[9];
  input_device *keyboard_devices[1];
  input_device *mouse_devices[1];
};

__asm__(".equ _vt$9input_mgr, 0x00504FB0");
__asm__(".equ __18AISurferController, 0x00100208");
__asm__(".equ insert_device__9input_mgrP12input_device, 0x00343B50");
__asm__(".equ scan_devices__9input_mgr, 0x001E2548");

input_mgr::input_mgr()
{
  flags = 0;

  int index = 0;

  for(index = 0; index < 9; ++index)
    joystick_devices[index] = 0;
  for(index = 0; index < 1; ++index)
    keyboard_devices[index] = 0;
  for(index = 0; index < 1; ++index)
    mouse_devices[index] = 0;

  joystick_devices[AI_JOYSTICK - JOYSTICK1_DEVICE] = new AISurferController();
  joystick_devices[AI_JOYSTICK - JOYSTICK1_DEVICE]->device_id = AI_JOYSTICK;
  insert_device(joystick_devices[AI_JOYSTICK - JOYSTICK1_DEVICE]);
  scan_devices();

  rumble_ptr = 0;

  SetDefaultController(0);
}
